(() => {
  const Z=window.Zucco,{state,platform:P,ui:U,ROUTES:R,escape:E,btn:BT,money:M}=Z;
  const error=message=>{const e=document.getElementById('ext-form-error');if(e){e.textContent=message;e.hidden=false;}};
  const details=(title,body,footer='')=>Z.actionDialog(`<div class="dialog-body"><div class="dialog-title-row"><h2 id="action-title">${E(title)}</h2>${BT('','close-action','close','ghost small')}</div>${body}</div><div class="dialog-footer">${BT('Close','close-action')}${footer}</div>`);
  const id=prefix=>prefix+'-'+crypto.randomUUID();
  const number=(values,name)=>Number(values.get(name)||0);
  const v=(values,name)=>String(values.get(name)||'').trim();
  const newStudent=()=>U.form('Add student','student',U.field('Full name','name','','text','required maxlength="70"')+U.field('Phone number','phone','','tel','required pattern="\\+?[0-9 ]{9,20}" placeholder="+998 90 123 45 67"')+U.select('Group','group',P.groups.map(g=>g.name))+U.select('Status','status',['Active','Trial','Frozen'])+U.field('Parent / guardian','parent','','text','maxlength="70"')+U.field('Parent phone','parentPhone','','tel'),'Create student');
  const newCourse=()=>U.form('Add course','course',U.field('Course name','name','','text','required maxlength="60"')+U.select('Subject','subject',['English language','Mathematics','Technology'])+U.select('Level','level',['Beginner','Foundation','Intermediate','Advanced','General'])+`<div class="settings-grid">${U.field('Duration, months','months',3,'number','required min="1" max="36"')}${U.field('Lessons / month','lessons',12,'number','required min="1" max="31"')}</div>`+U.field('Lesson duration, minutes','minutes',90,'number','required min="30" max="240" step="15"')+U.field('Monthly base fee, UZS','price',600000,'number','required min="1" max="999999999" step="1"'),'Create course');
  const newGroup=()=>U.form('Create group','group',U.field('Group name','name','','text','required maxlength="30" placeholder="e.g. IF-11"')+U.select('Course','course',P.courses.map(c=>[c.id,c.name]),P.selectedCourse)+U.select('Teacher','teacher',P.staff.filter(s=>s.role==='Teacher').map(s=>s.name))+U.select('Branch','branch',P.branches.map(b=>b.name))+`<div class="settings-grid">${U.select('Classroom','room',P.rooms.map(r=>r.name))}${U.field('Capacity','capacity',16,'number','required min="1" max="60"')}</div>`+U.select('Days','days',['Mon · Wed · Fri','Tue · Thu · Sat'])+U.select('Time','time',['09:00–10:30','11:00–12:30','14:00–15:30','16:00–17:30'])+U.select('Billing model','billing',['Monthly calendar','30-day cycle','Per lesson','Full course']),'Create group');
  const newStaff=()=>U.form('Add staff member','staff',U.field('Full name','name','','text','required maxlength="70"')+U.field('Phone','phone','','tel','required')+U.select('Role','role',['Teacher','Administrator','Cashier'])+U.select('Branch','branch',P.branches.map(b=>b.name))+U.field('Specialty / responsibility','specialty','','text','required maxlength="90"'),'Add staff');
  const newSMS=template=>U.form('Compose SMS','sms',U.field('Message title','name',template?.name||'November academy update','text','required maxlength="80"')+U.select('Audience','audience',[[String(P.students.length),'All students · '+P.students.length],['24','Students with outstanding tuition · 24'],['12','IELTS Foundation · 12'],['1','Azizbek Karimov · 1']])+`<label class="stack"><span class="field-label">Message text</span><textarea class="input" name="message" rows="5" required maxlength="480">${E(template?.body||'Hi {student_name}, a quick update from Zucco Academy.')}</textarea></label><p class="caption">Supported placeholders: {student_name}, {balance}, {course_name}, {branch_name}.</p>`,'Queue SMS');
  const setCoins=(s,amount)=>{if(s.id==='s1')state.coins=amount;s.coins=amount;const a=state.attendance.find(a=>a.id===s.id);if(a)a.coins=amount;};
  const renderProfile=Z.renderers[R.STUDENT];
  Z.renderers[R.STUDENT]=()=>{const s=Z.selectedStudent();let html;if(s.id==='s1')html=renderProfile();else{const balance=state.balance,coins=state.coins;state.balance=s.balance;state.coins=Z.studentCoins(s);try{html=renderProfile();}finally{state.balance=balance;state.coins=coins;}html=html.replaceAll('Azizbek Karimov',E(s.name)).replace('>AK</span>','>'+E(Z.initials(s.name))+'</span>').replaceAll('#ZU-0248','#'+s.code).replaceAll('+998 90 123 45 67',E(s.phone)).replaceAll('Dilshod Karimov',E(s.parent));}return html.replaceAll('data-action="send-sms"',`data-action="ext-student-sms:${s.id}"`).replaceAll('Edit profile','Contact note').replaceAll('data-action="payment"',`data-action="ext-student-payment:${s.id}"`).replaceAll('data-action="coin-history"',`data-action="ext-student-coins:${s.id}"`);};
  const grant=Z.reward;
  Z.reward=(studentId,amount)=>{const s=P.students.find(s=>s.id===studentId);if(s)P.coinLedger.unshift({name:s.name,amount,reason:'Classroom participation',balance:Z.studentCoins(s)+amount,time:'Just now'});grant(studentId,amount);};
  Object.assign(Z.extraHandlers,{
    'ext-new-student':newStudent,'ext-new-course':newCourse,'ext-new-group':newGroup,'ext-new-staff':newStaff,
    'ext-open-student':([student])=>{P.selectedStudent=student;state.profileTab='groups';Z.navigate(R.STUDENT);},
    'ext-open-course':([course])=>{P.selectedCourse=course;Z.navigate(R.COURSE);},'ext-open-group':([group])=>{P.selectedGroup=group;P.groupTab='students';Z.navigate(R.GROUP);},
    'ext-group-tab':([tab])=>{P.groupTab=tab;Z.render();},'ext-student-page':([direction])=>{const total=P.students.filter(s=>U.match('students',s.name,s.phone,s.code)&&(P.studentStatus===undefined||P.studentStatus==='all'||s.status===P.studentStatus)).length;P.studentPage=Math.max(1,Math.min(Math.ceil(total/8)||1,P.studentPage+Number(direction)));Z.render();},
    'ext-group-enroll':()=>U.form('Enroll a student','enrollment',U.select('Student','student',P.students.map(s=>[s.id,s.name]))+U.field('Joining date','joined','2026-11-02','date','required'),'Enroll in group',Z.selectedGroup().name+' · '+(Z.selectedGroup().capacity-Z.selectedGroup().enrolled)+' seats available'),
    'ext-new-branch':()=>U.form('Add branch','branch',U.field('Branch name','name','','text','required maxlength="50"')+U.field('Address','address','','text','required maxlength="120"')+U.field('Contact phone','phone','','tel','required'),'Create branch'),
    'ext-select-branch':([branch])=>{P.selectedBranch=branch;Z.render();},'ext-new-room':()=>U.form('Add classroom','room',U.select('Branch','branch',P.branches.map(b=>[b.id,b.name]),P.selectedBranch)+U.field('Room name / number','name','','text','required maxlength="30"')+U.select('Type','type',['Classroom','Computer lab'])+U.field('Capacity','capacity',16,'number','required min="1" max="100"'),'Add classroom'),
    'ext-staff-details':([staff])=>{const s=P.staff.find(s=>s.id===staff);if(!s)return;details(s.name,`<p class="caption">${E(s.specialty)}</p><div class="conversion-details"><div class="detail-row"><span>Role</span><strong>${s.role}</strong></div><div class="detail-row"><span>Branch</span><strong>${s.branch}</strong></div><div class="detail-row"><span>Phone</span><strong>${s.phone}</strong></div><div class="detail-row"><span>Teaching groups</span><strong>${s.groups}</strong></div></div>`,BT('Review role access','ext-role-from-staff:'+s.role,'shield','primary'));},
    'ext-role-from-staff':([role])=>{P.selectedRole=role;Z.closeAction();Z.navigate(R.ROLES);},
    'ext-new-payroll':()=>U.form('Calculate teacher salary','payroll',U.select('Teacher','teacher',P.staff.filter(s=>s.role==='Teacher').map(s=>s.name))+U.field('Completed lessons','lessons',24,'number','required min="1" max="120"')+U.field('Rate per lesson, UZS','rate',150000,'number','required min="1" max="9999999"')+U.field('Bonus, UZS','bonus',0,'number','required min="0" max="99999999"')+U.field('Deduction, UZS','deduction',0,'number','required min="0" max="99999999"'),'Save calculation',P.budgetPeriod+' · Only completed, attendance-marked lessons are eligible.'),
    'ext-payroll-review':([salary])=>{const p=P.payroll.find(p=>p.id===salary);if(!p)return;details('Review salary calculation',`<p class="caption">${p.teacher} · ${P.budgetPeriod}</p><div class="conversion-details"><div class="detail-row"><span>Completed lessons</span><strong>${p.lessons}</strong></div><div class="detail-row"><span>Calculated salary</span><strong>${M(p.base,true)}</strong></div><div class="detail-row"><span>Bonus</span><strong>+${M(p.bonus,true)}</strong></div><div class="detail-row"><span>Deduction</span><strong>−${M(p.deduction,true)}</strong></div><div class="detail-row"><span>Final amount</span><strong class="text-primary">${M(Z.payrollAmount(p),true)}</strong></div></div>`,p.status==='Draft'?BT('Approve calculation','ext-payroll-approve:'+p.id,'checkCircle','primary'):'');},
    'ext-payroll-approve':([salary])=>{const p=P.payroll.find(p=>p.id===salary);if(!p||p.status!=='Draft')return;p.status='Approved';Z.closeAction();Z.render();Z.toast('Salary calculation approved');},
    'ext-payroll-pay':([salary])=>{const p=P.payroll.find(p=>p.id===salary);if(!p||p.status!=='Approved')return;U.form('Confirm salary payment','salary-payment',`<input type="hidden" name="salary" value="${p.id}">`+U.field('Teacher','teacher',p.teacher,'text','readonly')+U.field('Approved amount, UZS','amount',Z.payrollAmount(p),'number','readonly')+U.select('Cash account','account',['Yunusobod cash desk','Academy operating account']),'Pay approved salary','The complete approved amount will be recorded as one salary expense.');},
    'ext-market-tab':([tab])=>{P.marketTab=tab;Z.render();},'ext-new-reward':()=>U.form('Add market reward','reward',U.field('Reward name','name','','text','required maxlength="60"')+U.field('Description','description','','text','required maxlength="110"')+U.field('Price in coins','price',120,'number','required min="1" max="100000"')+U.field('Stock quantity','stock',10,'number','required min="0" max="10000"'),'Add reward'),
    'ext-redeem':([item])=>{const m=P.market.find(m=>m.id===item);if(!m||m.stock<=0)return;U.form('Redeem reward','redemption',`<input type="hidden" name="item" value="${m.id}">`+U.select('Student','student',P.students.map(s=>[s.id,s.name+' · '+Z.studentCoins(s)+' Coins']))+`<div class="conversion-details"><div class="detail-row"><span>Reward</span><strong>${E(m.name)}</strong></div><div class="detail-row"><span>Price</span><strong class="text-warning">${m.price} Coins</strong></div><div class="detail-row"><span>Available stock</span><strong>${m.stock}</strong></div></div>`,'Confirm redemption');},
    'ext-deliver':([order])=>{const o=P.orders.find(o=>o.id===order);if(o){o.status='Delivered';Z.render();Z.toast('Reward marked as delivered');}},
    'ext-award-coins':()=>U.form('Award student coins','coins',U.select('Student','student',P.students.map(s=>[s.id,s.name]))+U.field('Coin amount','amount',5,'number','required min="1" max="1000"')+U.select('Reason','reason',['Classroom participation','Homework completed','Excellent performance','Weekly progress'])+U.field('Note','note','','text','maxlength="140"'),'Award coins'),
    'ext-student-coins':([student])=>{P.filters.coins=P.students.find(s=>s.id===student)?.name||'';Z.navigate(R.COINS);},
    'ext-student-payment':([student])=>{const s=P.students.find(s=>s.id===student);if(!s)return;Z.openPayment();state.paymentStudent=s.name;state.amount=Math.max(1,-Z.studentBalance(s));document.getElementById('payment-dialog').innerHTML=Z.renderPayment();},
    'ext-student-sms':([student])=>{const s=P.students.find(s=>s.id===student);if(!s)return;U.form('Message '+s.name,'sms',`<input type="hidden" name="audience" value="1">`+U.field('Message title','name','Student update','text','required maxlength="80"')+`<p class="caption">To ${E(s.phone)}</p><label class="stack"><span class="field-label">Message</span><textarea class="input" name="message" rows="4" required maxlength="480">Hi ${E(s.name.split(' ')[0])}, a quick update from Zucco Academy.</textarea></label>`,'Queue SMS');},
    'ext-sms-tab':([tab])=>{P.smsTab=tab;Z.render();},'ext-new-sms':()=>newSMS(),'ext-use-template':([index])=>newSMS(P.templates[Number(index)]),
    'ext-sms-preview':([sms])=>{const s=P.sms.find(s=>s.id===sms);if(!s)return;details(s.name,`<div class="template-preview">${E(s.body||P.templates[0].body)}</div><div class="conversion-details"><div class="detail-row"><span>Audience</span><strong>${s.audience}</strong></div><div class="detail-row"><span>Provider status</span>${U.status(s.status)}</div><div class="detail-row"><span>Created</span><strong>${s.time}</strong></div></div>`);},
    'ext-settings-tab':([tab])=>{P.settingsTab=tab;Z.render();},'ext-save-preferences':()=>{state.collapsed=P.preferences?.sidebar??state.collapsed;state.printReceipt=P.preferences?.receipts??true;Z.render();Z.toast('Workspace preferences saved locally');},'ext-select-role':([role])=>{P.selectedRole=role;Z.render();},'ext-save-roles':()=>Z.toast('Role permissions saved in this prototype'),
    'ext-show-password':()=>{const p=document.getElementById('demo-password');p.type=p.type==='password'?'text':'password';},'ext-forgot-password':()=>details('Demo sign-in',`<p class="caption">This is a local design prototype. The prefilled phone and password open the sample workspace; no account recovery or credential transmission is performed.</p>`),'ext-login-help':()=>details('Your academy workspace',`<p class="caption">Ask your academy administrator for workspace access. For this local concept, use the prefilled demo sign-in form.</p>`),
    'ext-export-students':()=>Z.downloadCSV('zucco-students.csv',[['Student','Phone','Group','Status','Balance UZS','Coins'],...P.students.map(s=>[s.name,s.phone,s.group,s.status,Z.studentBalance(s),Z.studentCoins(s)])]),
    'ext-export-report':()=>Z.downloadCSV('zucco-report-november.csv',[['Course','Enrollments','Monthly base fee UZS'],...P.courses.map(c=>[c.name,c.students,c.price])])
  });
  Z.handleExtraInput=t=>{const list=t.dataset.listSearch;if(!list)return;P.filters[list]=t.value;if(list==='students')P.studentPage=1;const body=document.getElementById(list+'-rows');if(body){const rows=Z.listRenderers[list]?.()||'';body.innerHTML=rows||(body.tagName==='TBODY'?`<tr><td colspan="10"><div class="empty-state">No matching records.</div></td></tr>`:'<div class="empty-state">No matching records.</div>');}};
  Z.handleExtraChange=t=>{if(t.dataset.extraFilter==='students-status'){P.studentStatus=t.value;P.studentPage=1;Z.render();}if(t.dataset.extraFilter==='group-status'){P.groupFilter=t.value;Z.render();}if(t.hasAttribute('data-payroll-period')){P.budgetPeriod=t.value;Z.render();}if(t.dataset.preference){P.preferences??={};P.preferences[t.dataset.preference]=t.checked;}if(t.dataset.permission&&!t.disabled){P.roleOverrides[t.dataset.permission]=t.checked;}if(t.hasAttribute('data-report-period'))Z.toast('Reporting period selected · Sample report shown');};
  Z.handleExtraSubmit=(form,values)=>{
    if(form.id==='demo-login-form'){Z.navigate(R.DASHBOARD);Z.toast('Demo workspace opened');return;}
    if(form.id==='organization-form'){for(const key of['name','phone','email','timezone','language','currency'])P.organization[key]=v(values,key);Z.toast('Academy profile saved locally');return;}
    const kind=form.dataset.kind;
    if(kind==='student'){const phone=v(values,'phone');if(P.students.some(s=>s.phone.replaceAll(' ','')===phone.replaceAll(' ',''))){error('A student with this phone number already exists.');return;}P.students.unshift({id:id('s'),name:v(values,'name'),phone,code:'ZU-'+(249+P.students.length-20),group:v(values,'group'),status:v(values,'status'),parent:v(values,'parent')||'Parent / guardian',parentPhone:v(values,'parentPhone'),balance:0,coins:0});P.studentPage=1;P.filters.students='';}
    if(kind==='course')P.courses.push({id:id('c'),name:v(values,'name'),subject:v(values,'subject'),level:v(values,'level'),months:number(values,'months'),lessons:number(values,'lessons'),minutes:number(values,'minutes'),price:number(values,'price'),groups:0,students:0,status:'Draft',icon:'book',description:'A new learning path for your academy.'});
    if(kind==='group'){const name=v(values,'name');if(P.groups.some(g=>g.name.toLowerCase()===name.toLowerCase())){error('Choose a unique group name.');return;}const course=P.courses.find(c=>c.id===v(values,'course'));P.groups.unshift({id:id('g'),name,course:course.id,teacher:v(values,'teacher'),branch:v(values,'branch'),room:v(values,'room'),days:v(values,'days'),time:v(values,'time'),capacity:number(values,'capacity'),enrolled:0,status:'Recruiting',price:course.price,billing:v(values,'billing')});course.groups++;}
    if(kind==='enrollment'){const g=Z.selectedGroup(),s=P.students.find(s=>s.id===v(values,'student'));if(g.enrolled>=g.capacity){error('This group has no seats available.');return;}if(s.group===g.name){error('This student is already enrolled in the group.');return;}s.group=g.name;g.enrolled++;}
    if(kind==='branch'){P.branches.push({id:id('b'),name:v(values,'name'),address:v(values,'address'),phone:v(values,'phone'),main:false,status:'Active'});}
    if(kind==='room'){if(P.rooms.some(r=>r.branch===v(values,'branch')&&r.name===v(values,'name'))){error('This room already exists in the selected branch.');return;}P.rooms.push({id:id('r'),branch:v(values,'branch'),name:v(values,'name'),type:v(values,'type'),capacity:number(values,'capacity'),status:'Available'});P.selectedBranch=v(values,'branch');}
    if(kind==='staff')P.staff.push({id:id('u'),name:v(values,'name'),phone:v(values,'phone'),role:v(values,'role'),specialty:v(values,'specialty'),branch:v(values,'branch'),groups:0,status:'Active'});
    if(kind==='payroll'){const teacher=v(values,'teacher'),existing=P.payroll.find(p=>p.teacher===teacher);if(existing?.status==='Paid'){error('A paid salary cannot be recalculated.');return;}const base=number(values,'lessons')*number(values,'rate'),bonus=number(values,'bonus'),deduction=number(values,'deduction');if(base+bonus-deduction<=0){error('The final salary amount must be positive.');return;}const record={id:existing?.id||id('pay'),teacher,lessons:number(values,'lessons'),students:24,scheme:'Per completed lesson',base,bonus,deduction,status:'Draft'};if(existing)Object.assign(existing,record);else P.payroll.push(record);}
    if(kind==='salary-payment'){const p=P.payroll.find(p=>p.id===v(values,'salary'));if(!p||p.status!=='Approved'||number(values,'amount')!==Z.payrollAmount(p)){error('Only the full approved amount can be paid once.');return;}p.status='Paid';const amount=Z.payrollAmount(p);state.expenses+=amount;state.transactions.unshift({id:'EXP-'+Date.now(),name:'Salary · '+p.teacher,course:'Teacher payroll · '+P.budgetPeriod,amount,method:'Cash',time:'10:48',kind:'expense'});}
    if(kind==='reward')P.market.push({id:id('m'),name:v(values,'name'),description:v(values,'description'),price:number(values,'price'),stock:number(values,'stock'),icon:'book'});
    if(kind==='redemption'){const m=P.market.find(m=>m.id===v(values,'item')),s=P.students.find(s=>s.id===v(values,'student'));if(!m||m.stock<1){error('This reward is out of stock.');return;}if(Z.studentCoins(s)<m.price){error('This student does not have enough coins for this reward.');return;}const balance=Z.studentCoins(s)-m.price;setCoins(s,balance);m.stock--;P.orders.unshift({id:'ORD-'+(110+P.orders.length-2),student:s.name,item:m.name,price:m.price,status:'Pending'});P.coinLedger.unshift({name:s.name,amount:-m.price,reason:m.name,balance,time:'Just now'});}
    if(kind==='coins'){const s=P.students.find(s=>s.id===v(values,'student')),amount=number(values,'amount'),balance=Z.studentCoins(s)+amount;setCoins(s,balance);P.coinLedger.unshift({name:s.name,amount,reason:v(values,'reason'),balance,time:'Just now'});P.filters.coins='';}
    if(kind==='sms'){P.sms.unshift({id:'SMS-'+(119+P.sms.length-5),name:v(values,'name'),body:v(values,'message'),audience:v(values,'audience')+' students',type:'General notice',status:'Pending',time:'Just now'});P.smsTab='history';}
    Z.closeAction();Z.render();Z.toast({student:'Student added',course:'Course created',group:'Group created',enrollment:'Student enrolled',branch:'Branch added',room:'Classroom added',staff:'Staff member added',payroll:'Salary calculation saved', 'salary-payment':'Salary paid in full',reward:'Reward added',redemption:'Reward reserved for collection',coins:'Student coins awarded',sms:'SMS queued in this prototype'}[kind]||'Saved');
  };
})();
